def max_path_sum(triangle, k, l):
    if k == 0:
        return 0
    if l == 0:
        return 0
    if l == 1:
        return triangle[k][l-1]
    if l == 2:
        return max(triangle[k][l-1], triangle[k][l-2] + triangle[k][l-1])
    return max(triangle[k][l-1], max(triangle[k][l-2] + triangle[k][l-1], triangle[k][l-3] + triangle[k][l-2] + triangle[k][l-1]))

def sum_digits_twoparts(num):
    num_str = str(num)
    max_sum = 0
    max_part = 0
    for i in range(len(num_str)):
        for j in range(i+1, len(num_str)):
            part_sum = sum(int(num_str[i]) + int(num_str[j]))
            if part_sum > max_sum:
                max_sum = part_sum
                max_part = int(num_str[i]) + int(num_str[j])
    return max_part

def longest_subseq_with_diff_one(arr, diff):
    n = len(arr)
    dp = [[0] * (diff + 1) for _ in range(n)]
    for i in range(n):
        dp[i][0] = 1
    for i in range(1, n):
        for j in range(1, diff + 1):
            if arr[i] == arr[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j - 1] + 1
    return max(dp[n - 1])

