        return False
    if a == b:
        return True
    if a > b:
        for i in range(a, b+1):
            if a % i == 0 and b % i == 0:
                return False
    else:
        for i in range(a, b+1):
            if a % i == 0 and b % i == 0:
                return False
    return True

